#pragma once
// embedding_mm engine -- Preprocessed Multimodal Feature Tensor Bundle Loader.
//
// Provides a lightweight, zero-dependency C++ binary loader for `.mmfeat` files
// generated by `tools/preprocess.py` (which uses Google's official
// EmbeddingGemma-2 AutoProcessor).
//
// Keeping raw media decoding (JPEG/PNG/WAV/MP4) and CPU signal processing in Python
// keeps the LuisaCompute C++ engine 100% pure, cross-platform, and focused on
// GPU DSL mega-kernel execution.

#include <cstdint>
#include <filesystem>

#include <luisa/core/dll_export.h>
#include <luisa/core/stl/vector.h>

namespace luisa::embed_mm {

enum class ModalityKind : uint32_t {
    Image = 1u,
    Audio = 2u,
    Video = 3u,
    Multimodal = 4u
};

#pragma pack(push, 1)
struct FeatureBundleHeader {
    uint32_t magic{0x54464D4Du};// "MMFT"
    uint32_t version{1u};
    uint32_t modality{0u};// ModalityKind
    uint32_t num_frames{0u};
    uint32_t max_patches{0u};
    uint32_t num_patches_w{0u};
    uint32_t num_patches_h{0u};
    uint32_t num_soft_tokens{0u};
    uint32_t feat_dim{0u};
    uint32_t reserved[7]{};
};
#pragma pack(pop)

static_assert(sizeof(FeatureBundleHeader) == 64u, "FeatureBundleHeader must be 64 bytes");

struct ImageFeatures {
    luisa::vector<float> pixel_values;  // [max_patches * 768] in [0, 1]
    luisa::vector<int32_t> position_ids;// [max_patches * 2] (x, y)
    uint32_t num_patches_w{48u};
    uint32_t num_patches_h{48u};
    uint32_t num_soft_tokens{256u};
    uint32_t max_patches{2520u};
};

struct AudioFeatures {
    luisa::vector<float> features;// [num_frames * 128] log-mel features
    uint32_t num_frames{0u};      // T (e.g. 307)
    uint32_t num_features{128u};  // 128 Mel channels
    uint32_t num_soft_tokens{0u}; // Soft tokens after 4x subsampling (e.g. 77)
};

struct VideoFrameFeatures {
    luisa::vector<float> pixel_values;  // [max_patches * 768] in [0, 1]
    luisa::vector<int32_t> position_ids;// [max_patches * 2] (x, y)
};

struct VideoFeatures {
    luisa::vector<VideoFrameFeatures> frames;
    luisa::vector<uint32_t> input_ids;// Optional pre-tokenized sequence (e.g. with mm:ss timestamps)
    uint32_t num_frames{0u};
    uint32_t num_soft_tokens_per_frame{0u};
    uint32_t total_soft_tokens{0u};
    uint32_t num_patches_w{0u};
    uint32_t num_patches_h{0u};
    uint32_t max_patches{1260u};
};

struct MultimodalFeatures {
    luisa::vector<uint32_t> input_ids;// Sequence token IDs with <|image|>, <|audio|>, <|video|> placeholders
    luisa::vector<ImageFeatures> images;
    luisa::vector<AudioFeatures> audios;
    luisa::vector<VideoFeatures> videos;
};

class FeatureLoader {
public:
    // Resolves path or automatically appends/replaces extension with `.mmfeat` if needed
    [[nodiscard]] static std::filesystem::path resolve_feat_path(const std::filesystem::path &path);

    [[nodiscard]] static ModalityKind peek_modality(const std::filesystem::path &path);

    [[nodiscard]] static ImageFeatures load_image(const std::filesystem::path &path);
    [[nodiscard]] static AudioFeatures load_audio(const std::filesystem::path &path);
    [[nodiscard]] static VideoFeatures load_video(const std::filesystem::path &path);
    [[nodiscard]] static MultimodalFeatures load_multimodal(const std::filesystem::path &path);
};

}// namespace luisa::embed_mm
